import type { CSSProperties } from "react";
import colors from "@/content/image-colors.json";

/**
 * Placeholder colour for photo frames (W10.2). `src/content/image-colors.json` holds the average colour of each
 * photo in public/images (generated by `python -I scripts/image-colors.py`; re-run after adding photos).
 * Painted as the <img>'s own background, so a frame shows the photo's colour while it downloads instead of an
 * empty box; object-cover hides it completely once the photo is there.
 */
const map = colors as Record<string, string>;

export function photoColor(src: string): string | undefined {
  return map[src];
}

/** `style` for a next/image: the placeholder colour merged under any style of its own. */
export function photoStyle(src: string, style?: CSSProperties): CSSProperties | undefined {
  const c = map[src];
  if (!c) return style;
  return { backgroundColor: c, ...style };
}

/**
 * Scale a `sizes` attribute by a crop zoom (> 1 enlarges the photo inside its frame, so it needs more pixels):
 * "(min-width: 1024px) 30vw, 78vw" x 1.3 -> "(min-width: 1024px) calc(30vw * 1.3), calc(78vw * 1.3)".
 */
export function zoomSizes(sizes: string, zoom = 1): string {
  if (!zoom || zoom === 1) return sizes;
  const parts: string[] = [];
  let depth = 0;
  let cur = "";
  for (const ch of sizes) {
    if (ch === "(") depth++;
    if (ch === ")") depth--;
    if (ch === "," && depth === 0) {
      parts.push(cur.trim());
      cur = "";
    } else cur += ch;
  }
  if (cur.trim()) parts.push(cur.trim());
  return parts
    .map((p) => {
      const m = /^(\(.*\))\s+(.+)$/.exec(p);
      const [media, len] = m ? [m[1] + " ", m[2]] : ["", p];
      return `${media}calc(${len.replace(/^calc/, "")} * ${zoom})`;
    })
    .join(", ");
}
